class CAPA {
  constructor(id, tenantId, region) {
    this.id = id;
    this.tenantId = tenantId;
    this.region = region;
    this.evidence = [];
    this.rootCause = null;
    this.actions = [];
    this.owner = null;
    this.state = 'DETECTED';
    this.timestamps = {};
  }
}
